Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_prepend_resize_failure(void) {
    // Setup: create a buffer with content "World"
    buffer_t *buf = helper_create_buffer_with_content("World");
    TEST_ASSERT_NOT_NULL(buf);

    // The buffer's allocated size is exactly strlen("World") == 5
    // Prepending "Hello" (len=5) will require resizing (needed=10 > 5)
    // We want buffer_resize to fail, which is the first allocation after setup (2 allocs)
    malloc_fail_after(2); // 2 allocs for buffer creation, fail the 3rd (realloc in buffer_resize)

    int ret = buffer_prepend(buf, "Hello");
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer should still be valid, but its content should be unchanged
    helper_assert_buffer_content(buf, "World");
    helper_assert_buffer_length(buf, 5);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_failure);
    return UNITY_END();
}


